import { test, expect } from '@playwright/test';

test.describe('Sauce Labs Backpack Add/Remove Tests', () => {
  test('should add the backpack to the cart', async ({ page }) => {
    await test.beforeEach(async ({ page }) => {
      await page.goto('https://www.saucedemo.com');
      await page.login('standard_user', 'secret_sauce');
    });
    await page.click('[data-test="add-to-cart-sauce-labs-backpack"]');
    await expect(page.locator('.shopping_cart_badge')).toBeVisible();
    await expect(page.locator('.shopping_cart_badge')).toHaveURL('https://www.saucedemo.com/cart');
  });

  test('should not change the URL when removing the backpack', async ({ page }) => {
    await test.beforeEach(async ({ page }) => {
      await page.goto('https://www.saucedemo.com');
      await page.login('standard_user', 'secret_sauce');
      await page.click('[data-test="add-to-cart-sauce-labs-backpack"]');
    });
    await page.click('[data-test="remove-sauce-labs-backpack"]');
    await expect(page.locator('.shopping_cart_badge')).toBeVisible();
    await expect(page.locator('.shopping_cart_badge')).toHaveURL('https://www.saucedemo.com/cart');
  });
});
